<?php use App\Core\Auth; use App\Services\Finance; ?><div class="toolbar no-print"><a class="text-link" href="<?= e(url('invoices')) ?>">← All invoices</a><button class="button" data-print>Print / save PDF</button></div><section class="panel document"><div class="document-head"><div><h2><?= e($school['name']) ?></h2><p><?= e($school['address']) ?><br><?= e($school['phone'].' · '.$school['email']) ?></p></div><div><p class="eyebrow">INVOICE</p><h2><?= e($invoice['number']) ?></h2><?php badge(Finance::status($invoice)); ?></div></div><div class="detail-grid"><div><small>Billed to</small><strong><?= e($student['first_name'].' '.$student['last_name']) ?></strong><span><?= e($student['admission_number']) ?></span></div><div><small>Issued</small><strong><?= e($invoice['issued_on']) ?></strong></div><div><small>Due</small><strong><?= e($invoice['due_on']) ?></strong></div></div><table><thead><tr><th>Description</th><th class="num">Amount · <?= e($school['currency']) ?></th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?= e($item['description']) ?></td><td class="num"><?= money($item['amount']) ?></td></tr><?php endforeach; foreach($adjustments as $a): ?><tr><td><?= e($a['kind']) ?><small><?= e($a['posted_on'].' · '.$a['reason']) ?></small></td><td class="num"><?= money($a['amount']) ?></td></tr><?php endforeach ?></tbody><tfoot><tr><th>Total billed</th><th class="num"><?= money($invoice['total']) ?></th></tr><tr><th>Payments</th><th class="num"><?= money($invoice['paid']) ?></th></tr><tr class="total-row"><th>Outstanding</th><th class="num"><?= $invoice['cancelled_at']?'Cancelled':money($invoice['balance']) ?></th></tr></tfoot></table><?php if($invoice['cancelled_at']): ?><p class="note">Cancelled: <?= e($invoice['cancellation_reason']) ?></p><?php endif ?></section>
<?php if(!$invoice['cancelled_at']): ?>
<?php if(Auth::can('payments.write') && (int)$invoice['balance']>0): ?><section class="panel no-print"><h2>Record a payment</h2><p class="muted">Payment and receipt are saved together. Outstanding: <?= e($school['currency']) ?> <?= money($invoice['balance']) ?>.</p><?php startForm('payment.create',['invoice_id'=>$invoice['id'],'request_key'=>bin2hex(random_bytes(24))]); field('amount','Amount received','number'); field('paid_on','Payment date','date',date('Y-m-d')); selectField('method','Payment method',['Cash','Bank','Mobile Money','Cheque','Other'],'Cash'); field('reference','Reference · required except cash','text','',false); field('notes','Notes','text','',false); ?><div class="form-actions"><button class="button primary" data-confirm="Record this payment and issue its receipt?">Record payment & issue receipt</button></div></form></section><?php endif ?>
<?php if(Auth::can('invoices.write')): ?><details class="panel no-print"><summary>Post an adjustment</summary><p class="muted">Discounts and credits reduce the balance. Additional charges and penalties increase it. Use a signed amount for a general adjustment.</p><?php startForm('invoice.adjust',['invoice_id'=>$invoice['id']]); selectField('kind','Adjustment type',['Additional charge','Discount','Penalty','Adjustment','Credit']); field('amount','Amount','number'); field('reason','Reason'); endForm('Post adjustment'); ?></details><details class="panel no-print"><summary>Cancel invoice</summary><p class="muted">Posted payments must first be reversed. A cancelled invoice is retained permanently.</p><?php startForm('invoice.cancel',['invoice_id'=>$invoice['id']]); field('reason','Cancellation reason'); ?><div class="form-actions"><button class="button danger" data-confirm="Cancel this invoice? Its history will be preserved.">Cancel invoice</button></div></form></details><?php endif; endif ?>
